"""Writes mockup/scenario-data.js from presets/formations.json, so the scenario mockup never retypes a position."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
formations = json.loads((root / "presets/formations.json").read_text())["formations"]
slim = [{"id": f["id"], "name": f["name"], "pitch": f["pitch"],
         "slots": [[s["number"], s["roleID"], s["x"], s["y"]] for s in f["slots"]]} for f in formations]
(root / "mockup/scenario-data.js").write_text(
    "// Generated by mockup/gen_scenario_data.py from presets/formations.json; do not edit by hand.\n"
    "// [number, roleID, x, y] per slot: x across 0 (left) to 1, y up the pitch from our goal (0) to theirs (1).\n"
    "const FORMATIONS = " + json.dumps(slim, separators=(",", ":")) + ";\n")
